import React, { useState, useEffect } from "react";
import axios from "axios";
import "bootstrap/dist/css/bootstrap.min.css";
import live from "../../img/aulas-ao-vivo-coursifyme.jpg";

const LecionaAula = () => {
  const [materiais, setMateriais] = useState([]);
  const [cursos, setCursos] = useState([]);
  const [cursoSelecionado, setCursoSelecionado] = useState("");
  const [aulas, setAulas] = useState([]);
  const [novaAula, setNovaAula] = useState({
    titulo: "",
    arquivo: null,
  });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Carregar cursos, materiais e aulas ao montar o componente
  useEffect(() => {
    const carregarDados = async () => {
      try {
        setLoading(true);

        // Carregar cursos
        const cursosResponse = await axios.get("/api/cursos");
        setCursos(cursosResponse.data);

        // Carregar materiais (substitua pela sua chamada API real)
        const materiaisResponse = await axios.get("/api/materiais");
        setMateriais(materiaisResponse.data);

        // Carregar aulas (substitua pela sua chamada API real)
        const aulasResponse = await axios.get("/api/aulas");
        setAulas(aulasResponse.data);

        setLoading(false);
      } catch (err) {
        console.error("Erro ao carregar dados:", err);
        setError("Erro ao carregar dados. Tente novamente mais tarde.");
        setLoading(false);
      }
    };

    carregarDados();
  }, []);

  // Carregar aulas quando o curso selecionado mudar
  useEffect(() => {
    if (cursoSelecionado) {
      const carregarAulasDoCurso = async () => {
        try {
          const response = await axios.get(
            `/api/cursos/${cursoSelecionado}/aulas`
          );
          setAulas(response.data);
        } catch (err) {
          console.error("Erro ao carregar aulas do curso:", err);
        }
      };
      carregarAulasDoCurso();
    }
  }, [cursoSelecionado]);

  // Manipulador para upload de arquivo de material
  const handleFileUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const formData = new FormData();
    formData.append("arquivo", file);

    try {
      const response = await axios.post("/api/materiais", formData, {
        headers: {
          "Content-Type": "multipart/form-data",
        },
      });
      setMateriais([...materiais, response.data]);
    } catch (error) {
      console.error("Erro ao enviar arquivo:", error);
      alert("Erro ao enviar arquivo. Tente novamente.");
    }
  };

  // Remover material
  const removerMaterial = async (id) => {
    try {
      await axios.delete(`/api/materiais/${id}`);
      setMateriais(materiais.filter((material) => material.id !== id));
    } catch (error) {
      console.error("Erro ao remover material:", error);
      alert("Erro ao remover material. Tente novamente.");
    }
  };

  // Adicionar nova aula (vídeo)
  const adicionarAula = async () => {
    if (!novaAula.titulo || !novaAula.arquivo || !cursoSelecionado) {
      alert("Preencha todos os campos obrigatórios");
      return;
    }

    const formData = new FormData();
    formData.append("titulo", novaAula.titulo);
    formData.append("arquivo", novaAula.arquivo);
    formData.append("cursoId", cursoSelecionado);

    try {
      const response = await axios.post("/api/aulas", formData, {
        headers: {
          "Content-Type": "multipart/form-data",
        },
      });

      // Atualiza a lista de aulas com a nova aula adicionada
      setAulas([...aulas, response.data]);

      alert("Aula adicionada com sucesso!");
      setNovaAula({ titulo: "", arquivo: null });
    } catch (error) {
      console.error("Erro ao adicionar aula:", error);
      alert("Erro ao adicionar aula. Tente novamente.");
    }
  };

  // Remover aula
  const removerAula = async (id) => {
    try {
      await axios.delete(`/api/aulas/${id}`);
      setAulas(aulas.filter((aula) => aula.id !== id));
      alert("Aula removida com sucesso!");
    } catch (error) {
      console.error("Erro ao remover aula:", error);
      alert("Erro ao remover aula. Tente novamente.");
    }
  };

  if (loading) return <div className="text-center mt-5">Carregando...</div>;
  if (error) return <div className="alert alert-danger mt-5">{error}</div>;

  return (
    <div
      className="container-fluid d-flex flex-column align-items-center"
      style={{
        backgroundColor: "#E7EFF4",
        minHeight: "100vh",
        padding: "20px",
      }}
    >
      {/* ... (código anterior da navegação e cabeçalho) ... */}

      <div className="d-flex justify-content-between w-75">
        {/* Seção de Aulas Ao Vivo (mantida igual) */}

        <div className="w-50">
          <div className="d-flex justify-content-between align-items-center mb-2">
            <h4>Aulas Gravadas</h4>
          </div>

          {/* Seletor de Cursos */}
          <div className="mb-3">
            <label className="form-label">Selecione o Curso</label>
            <select
              className="form-select"
              value={cursoSelecionado}
              onChange={(e) => setCursoSelecionado(e.target.value)}
            >
              <option value="">Selecione um curso</option>
              {cursos.map((curso) => (
                <option key={curso.id} value={curso.id}>
                  {curso.nome} - {curso.nivel} ({curso.area})
                </option>
              ))}
            </select>
          </div>

          {/* Formulário para adicionar nova aula (só aparece quando um curso é selecionado) */}
          {cursoSelecionado && (
            <div className="card p-3 mb-3">
              <h5>Adicionar Nova Aula</h5>
              <div className="mb-3">
                <label className="form-label">Título da Aula</label>
                <input
                  type="text"
                  className="form-control"
                  value={novaAula.titulo}
                  onChange={(e) =>
                    setNovaAula({ ...novaAula, titulo: e.target.value })
                  }
                  placeholder="Ex: Aula 01 - Introdução ao React"
                />
              </div>
              <div className="mb-3">
                <label className="form-label">
                  Vídeo da Aula (MP4, MOV, etc.)
                </label>
                <input
                  type="file"
                  className="form-control"
                  accept="video/*"
                  onChange={(e) =>
                    setNovaAula({ ...novaAula, arquivo: e.target.files[0] })
                  }
                />
              </div>
              <button
                className="btn btn-primary"
                onClick={adicionarAula}
                disabled={!novaAula.titulo || !novaAula.arquivo}
              >
                Enviar Aula
              </button>
            </div>
          )}

          {/* Lista de Aulas */}
          <div className="card p-3">
            <h5>Aulas Disponíveis</h5>
            {aulas.length === 0 ? (
              <div className="text-center py-3">
                {cursoSelecionado
                  ? "Nenhuma aula disponível para este curso."
                  : "Selecione um curso para ver as aulas."}
              </div>
            ) : (
              <table className="table">
                <tbody>
                  {aulas.map((aula) => (
                    <tr key={aula.id}>
                      <td>
                        <a
                          href={`/aulas/${aula.id}`}
                          target="_blank"
                          rel="noopener noreferrer"
                        >
                          {aula.titulo}
                        </a>
                        <div className="text-muted small">
                          {new Date(aula.createdAt).toLocaleDateString()}
                        </div>
                      </td>
                      <td className="text-end">
                        <button className="btn btn-link p-1">✏️</button>
                        <button
                          className="btn btn-link p-1 text-danger"
                          onClick={() => removerAula(aula.id)}
                        >
                          🗑
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        </div>
      </div>

      {/* Seção de Materiais de Apoio (mantida similar) */}
    </div>
  );
};

export default LecionaAula;
